<?php
require "db.php";
$summary=$conn->query("SELECT COUNT(*) AS bill_count, COALESCE(SUM(total_weight),0) AS gross_weight, COALESCE(SUM(net_weight),0) AS net_weight, COALESCE(SUM(total_amount),0) AS amount FROM bills")->fetch_assoc();
$districts=$conn->query("SELECT district, COUNT(*) AS bill_count, COALESCE(SUM(total_weight),0) AS gross_weight, COALESCE(SUM(net_weight),0) AS net_weight, COALESCE(SUM(total_amount),0) AS amount FROM bills GROUP BY district ORDER BY amount DESC");
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JM PADDY | Reports</title><link rel="stylesheet" href="style.css"></head><body><div class="app"><aside class="sidebar"><h2>🌾 JM PADDY</h2><p class="subtitle">Paddy Billing System</p><nav><a href="dashboard.php">🏠 Dashboard</a><a href="bill.php">🧾 Create Bill</a><a href="farmers.php">👨‍🌾 Farmers</a><a href="history.php">📋 Bill History</a><a class="active" href="reports.php">📈 Reports</a><a href="prices.php">💰 Price Management</a><a href="settings.php">⚙️ Settings</a></nav></aside><main class="main"><header class="topbar"><div><h1>Reports</h1><p>Summary of saved bills by district.</p></div><button class="btn" onclick="window.print()">Print report</button></header><section class="cards"><div class="card"><h3>Total Bills</h3><strong style="font-size:28px;color:#174b30"><?= number_format((int)$summary["bill_count"]) ?></strong></div><div class="card"><h3>Gross Weight</h3><strong style="font-size:28px;color:#174b30"><?= number_format((float)$summary["gross_weight"],2) ?> kg</strong></div><div class="card"><h3>Total Bill Value</h3><strong style="font-size:clamp(20px,2.5vw,28px);color:#174b30">Rs. <?= number_format((float)$summary["amount"],2) ?></strong></div></section><section class="panel" style="margin-top:20px"><h2>District breakdown</h2><div style="overflow-x:auto"><table><thead><tr><th>District</th><th>Bills</th><th>Gross Weight</th><th>Net Weight</th><th>Total Amount</th></tr></thead><tbody><?php if($districts && $districts->num_rows): while($r=$districts->fetch_assoc()): ?><tr><td><?= htmlspecialchars($r["district"]) ?></td><td><?= (int)$r["bill_count"] ?></td><td><?= number_format((float)$r["gross_weight"],2) ?> kg</td><td><?= number_format((float)$r["net_weight"],2) ?> kg</td><td>Rs. <?= number_format((float)$r["amount"],2) ?></td></tr><?php endwhile; else: ?><tr><td colspan="5">No bills available for reporting.</td></tr><?php endif; ?></tbody></table></div></section></main></div></body></html>